<script setup lang="ts">
import { computed, ref, nextTick } from 'vue';
import { fixture } from '../foundationState';
import { recordsReview, type LearningRecord } from '../recordState';
const detail=ref<HTMLElement|null>(null);
const props=defineProps<{records:LearningRecord[]}>();
const emit=defineEmits<{maintenance:[]}>();
const purpose=ref(''),chosen=ref(''),opened=ref(''),description=ref(''),category=ref<'input'|'domain'|'evaluation'|'interaction'|'technical'|'unresolved'>('unresolved'),view=ref('case');
const current=computed(()=>props.records.find(r=>r.id===opened.value));
const issue=computed(()=>recordsReview.issues.find(i=>i.id===recordsReview.activeIssue));
function open(){if(!purpose.value.trim()||!chosen.value)return;opened.value=chosen.value;description.value='';recordsReview.access.push({recordId:chosen.value,purpose:purpose.value.trim(),at:new Date().toISOString()});nextTick(()=>detail.value?.scrollIntoView({block:'start'}));}
function createIssue(){if(!current.value||!description.value.trim())return;const id='REVIEW-'+crypto.randomUUID().slice(0,8);recordsReview.issues.push({id,recordId:current.value.id,purpose:recordsReview.access.at(-1)?.purpose||'',category:category.value,description:description.value.trim(),decision:'pending',linkedVersion:'',history:['从具体记录建立人工复核线索；未自动判定根因。']});recordsReview.activeIssue=id;description.value='';}
function decision(d:'nochange'|'unresolved'|'maintenance'){if(!issue.value)return;issue.value.decision=d;issue.value.history.push({nochange:'人工记录当前不修改；不代表模型质量通过。',unresolved:'保留未决，相关记录不删除。',maintenance:'转入领域候选维护；发布不自动解决本事项或历史影响。'}[d]);if(d==='maintenance')emit('maintenance');}
</script>
<template><main class="f-flow-page f-wide">
  <span class="f-eyebrow">管理员 · 按案例查看与人工复核</span><h1>从实际输入，查到帮助与判断依据</h1>
  <details class="f-provenance"><summary>本轮实际页面操作与未执行环节分开</summary><p>只读取当前浏览器的合成学习操作。按事项打开是产品入口演示，服务端授权未实现；Observation、Policy、Evidence、Belief 未运行，不补造它们的输入输出。</p></details>
  <div class="f-actions"><button :aria-pressed="view==='case'" @click="view='case'">按学习记录查看</button><button :aria-pressed="view==='definition'" @click="view='definition'">查看合成定义目录</button></div>
  <section v-if="view==='definition'" class="f-card"><h2>Domain 参考目录</h2><p>这里的对象用于既有维护演示，不表示任意输入已正式映射到它们。</p><article v-for="o in [fixture.definition,...fixture.supporting_objects]" :key="o.id" class="f-diff"><h3>{{ o.id }}@{{ o.version }} · {{ o.name }}</h3><pre>{{ JSON.stringify(o,null,2) }}</pre></article><button @click="emit('maintenance')">进入领域候选维护</button></section>
  <template v-else><section class="f-card"><h2>选定记录与查阅用途</h2><p v-if="!records.length">尚无实际提交。先在学生端求助、提交练习或结束一次检测，再回来追溯。普通记录同样可以抽查。</p><label class="f-field">相关记录<select v-model="chosen" aria-label="后台选择学习记录"><option value="">选择记录</option><option v-for="r in records" :key="r.id" :value="r.id">{{ r.id }} · {{ r.source }} · {{ r.hidden?'学生已隐藏 · ':'' }}{{ r.space }}</option></select></label><label class="f-field">本次事项或用途<textarea v-model="purpose" aria-label="本次查阅用途" placeholder="例如：核对某次识别更正与帮助背景，不填写真实儿童资料。"/></label><button class="f-secondary" :disabled="!chosen||!purpose.trim()" @click="open">按本次用途打开记录</button></section>
  <template v-if="current"><section ref="detail" class="f-card"><h2>{{ current.id }} · 事实与采用依据</h2><p>空间：{{ current.space }} · {{ current.version }}{{ current.hidden?' · 已从学生界面隐藏':'' }}</p><p>原题：{{ current.prompt }}</p><p>原提交：{{ current.answer||'没有作答' }}</p><p>帮助记录：{{ current.help }}</p><details v-if="current.input"><summary>核对原输入、转写与发送版本</summary><pre>{{ JSON.stringify(current.input,null,2) }}</pre></details><ol v-if="recordsReview.notes[current.id]?.length"><li v-for="(n,i) in recordsReview.notes[current.id]" :key="i">{{ n.kind==='retry'?'新尝试':'资料更正' }}：{{ n.text }}；{{ n.reason }}</li></ol></section>
    <section v-if="current.checks?.length" class="f-card"><h2>提交前的输入核对</h2><article v-for="c in current.checks" :key="c.id" class="f-answer"><p>原输入：{{ c.original }}</p><p>确认后：{{ c.corrected }}</p><p>学生说明：{{ c.reason }}</p><p class="f-muted">{{ c.at }} · 记录用户声明，没有自动认证修改性质或作答独立性。</p></article></section>
    <section class="f-card"><h2>逐层检查运行依据</h2><dl class="f-trace-list"><dt>Learning Space</dt><dd>采用关系：{{ current.space }}／{{ current.version }}。合成材料，不是实际教材覆盖。</dd><dt>Domain Space</dt><dd>没有正式题目映射提交。可查看合成参考目录，不能把相似题面当成已建立的模型关系。</dd><dt>Interaction / 事实与展示</dt><dd>原输入、实际提交及已记录的帮助如上。生成的候选、计划动作与实际展示不能互相替代。</dd><dt>Interaction / Observation、语义校验、Policy</dt><dd>未执行：当前原型未接入模型与正式责任层。不是校验 PASS，也不是合法决定不干预。</dd><dt>Evaluation / Evidence、Belief、目标评价</dt><dd>未执行：没有可追溯的正式推断，不填“0”、不设为掌握或不会，不把系统未运行解释成学习者证据不足。</dd><dt>Evolution / 人工维护事项</dt><dd>下方可保留具体差异、处理方向及候选关联；自动诊断和真实重处理没有运行。</dd></dl></section>
    <section class="f-card"><h2>记录差异，决定下一步</h2><label class="f-field">人工判断的处理方向<select v-model="category" aria-label="复核处理方向"><option value="unresolved">尚不能确定</option><option value="input">资料或识别</option><option value="domain">领域定义或映射</option><option value="evaluation">评价规则</option><option value="interaction">教学或交互规则</option><option value="technical">运行故障</option></select></label><label class="f-field">预期、实际与依据<textarea v-model="description" aria-label="复核差异说明"/></label><button :disabled="!description.trim()" @click="createIssue">建立人工复核事项</button></section>
  </template></template>
  <section v-if="recordsReview.issues.length" class="f-card"><h2>本轮复核事项</h2><label class="f-field">选择事项<select v-model="recordsReview.activeIssue" aria-label="选择复核事项"><option v-for="i in recordsReview.issues" :key="i.id" :value="i.id">{{ i.id }} · {{ i.recordId }}</option></select></label><template v-if="issue"><p>{{ issue.description }}</p><p>用途：{{ issue.purpose }} · 方向：{{ issue.category }} · 关联发布：{{ issue.linkedVersion||'尚无' }}</p><ol><li v-for="(entry,i) in issue.history" :key="i">{{ entry }}</li></ol><div class="f-actions"><button @click="decision('unresolved')">记录为仍未决</button><button @click="decision('nochange')">记录为当前不修改</button><button :disabled="issue.category!=='domain'" @click="decision('maintenance')">转入领域候选维护</button></div><p class="f-muted">只有明确为领域定义或映射时才转入此候选编辑器；其他方向保留事项，不冒用 Domain 修改解决。发布后仍需独立跟踪实际影响。</p></template></section>
  <details v-if="recordsReview.access.length" class="f-card"><summary>本轮查阅记录</summary><ol><li v-for="(a,i) in recordsReview.access" :key="i">{{ a.recordId }} · {{ a.purpose }} · {{ a.at }}</li></ol></details>
</main></template>
